import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Multi-Scene Product Video Production Pipeline (LTX Director, Wan 2.2 VACE / I2V Workers & CapCut Export)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/06-ai-media-and-video-studio/wan-vace-product-video-pipeline/spec.md","filePath":"feature/modules/06-ai-media-and-video-studio/wan-vace-product-video-pipeline/spec.md"}'),i={name:"feature/modules/06-ai-media-and-video-studio/wan-vace-product-video-pipeline/spec.md"};function d(n,e,c,s,l,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="multi-scene-product-video-production-pipeline-ltx-director-wan-2-2-vace-i2v-workers-capcut-export" tabindex="-1">Multi-Scene Product Video Production Pipeline (LTX Director, Wan 2.2 VACE / I2V Workers &amp; CapCut Export) <a class="header-anchor" href="#multi-scene-product-video-production-pipeline-ltx-director-wan-2-2-vace-i2v-workers-capcut-export" aria-label="Permalink to &quot;Multi-Scene Product Video Production Pipeline (LTX Director, Wan 2.2 VACE / I2V Workers &amp; CapCut Export)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>wan-vace-product-video-pipeline</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>06-ai-media-and-video-studio</code> — AI Commercial Image, Product Video &amp; Conversational Video Studio</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>product-video-pipeline</code>, <code>ltx-director-worker</code>, <code>i2v-worker-integration</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-10-view-video-style-template/spec.html">FR 3.7.10 — View Video Style Template</a> · <a href="./../../../srs/06-ai-features/3-7-11-generate-video/spec.html">FR 3.7.11 — Generate Video</a> · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Orchestrate multi-scene commercial <strong>Product Video Production</strong> (<code>ProductVideoController</code> + <code>product_video.py</code>): AI Director storyboard planning (<code>POST /plan</code> / <code>ltx-director-worker</code>), quote &amp; credit reservation (<code>product_video_quotes</code> + <code>ai_credit_reservations</code>), asynchronous <strong>Image-to-Video (I2V / Wan 2.2 VACE / LTX / Veo)</strong> per-scene generation (<code>i2v-worker-integration</code>), granular scene retry (<code>POST /scenes/{sceneId}/retry</code>), master MP4 stitching (<code>POST /render-retry</code>), and editable <strong>CapCut Desktop multi-track bundle export</strong> (<code>GET /{id}/editing-bundle</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code>, I want to turn product images and a campaign brief into a multi-scene storyboard, generate smooth I2V commercial shots, retry any individual scene without regenerating the whole video, and download either the final MP4 or an editable CapCut project bundle.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Two-Stage Storyboard Plan -&gt; Scene Generation (<code>product-video-pipeline</code>, <code>2026-10-30-product-video-pipeline.sql</code>):</strong> <code>POST /api/v1/workspaces/{workspaceId}/ai/video-productions/plan</code> synthesizes a scene-by-scene camera/motion script (<code>product_video_plans</code>) and exact credit quote (<code>product_video_quotes</code>) before any GPU generation runs.</li><li><strong>LTX Director &amp; I2V GPU Worker Integration (<code>ltx-director-worker</code>, <code>i2v-worker-integration</code>):</strong> <code>POST /video-productions/{id}/generate</code> reserves <code>VIDEO_GENERATE</code> credits (<code>DA-974</code> <code>reservation_id</code>), dispatches reference-conditioned I2V scene jobs (<code>Wan 2.2 VACE</code> / <code>LTX-Video</code> / <code>Veo</code>), tracks <code>product_video_attempts</code>, and reconciles completion asynchronously even if the user closes the browser.</li><li><strong>Granular Scene Retry &amp; Render Retry:</strong> <code>POST /{id}/scenes/{sceneId}/retry</code> regenerates a single failed/unsatisfactory scene; <code>POST /{id}/render-retry</code> re-runs final FFmpeg concat/audio muxing without re-running GPU inference.</li><li><strong>Final MP4 &amp; CapCut Bundle Export:</strong> <code>GET /{id}/content</code> and <code>GET /{id}/scenes/{sceneId}/content</code> stream rendered MP4s; <code>GET /{id}/editing-bundle</code> (<code>tools/video-edit/package_capcut.py</code>) packages raw scene clips, beat markers (<code>beats.py</code>), and <code>draft_content.json</code> into a portable <code>.zip</code> for CapCut Desktop.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>aiStudio.productVideo.{plan,scenes,generate,retryScene,capcutBundle}.*</code> in <code>src/i18n/locales/{vi,en}/aiStudio.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/ai-studio/video.tsx</code>, <code>GenerateVideoDialog.tsx</code>, <code>pages/editor/components/AIVideoAssistPanel.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{AiVideoScreen,AiVideoHistoryScreen,QuickReelStudioScreen}.tsx</code>, <code>src/utils/aiWorkerHelpers.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/video-productions/plan</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>ProductVideoController.plan()</code> -&gt; <code>product_video.py</code> <code>POST /ai/product-video/plan</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/video-productions/{id}/generate</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>ProductVideoController.generate()</code> -&gt; reserves credits &amp; dispatches I2V scene workers</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/video-productions/{id}/scenes/{sceneId}/retry &amp; /render-retry</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>ProductVideoController</code> -&gt; granular scene or stitch recovery</td></tr><tr><td style="text-align:left;">`GET /api/v1/workspaces/{workspaceId}/ai/video-productions/{id}[/content</td><td style="text-align:left;">/editing-bundle]`</td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>User Closes Browser During Long GPU Render:</strong> Background reconciliation worker in <code>business-service</code> polls <code>GET /ai/product-video/render/{render_id}</code>, persists S3 output, and settles/releases <code>ai_credit_reservations</code> deterministically.</li><li><strong>Cross-User Job Isolation:</strong> Video job polling enforces Workspace/originator authorization checks.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-10-view-video-style-template/spec.html">FR 3.7.10 — View Video Style Template</a> · <a href="./../../../srs/06-ai-features/3-7-11-generate-video/spec.html">FR 3.7.11 — Generate Video</a> · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const h=t(i,[["render",d]]);export{g as __pageData,h as default};
